/**
 * Diagnostic error code registry (ADR-0016).
 *
 * - Codes look like `domain.short-slug`; domains come from a **closed vocabulary** (adding a domain requires an ADR).
 * - Domains split by "kind of error", not by stage of discovery: a unit mismatch is `value.*` no matter which layer finds it.
 * - A code is frozen once emitted: no changing meaning, no renaming, no reuse. If semantics change, emit a new code and mark the old one `[DEPRECATED → new.code]`.
 * - This file is the single source of truth; `docs/error-codes.md` is generated by `bun run gen:codes`, never hand-written.
 */

/** Domain vocabulary (closed). */
export const DIAGNOSTIC_DOMAINS = [
  "syntax",
  "value",
  "ref",
  "contract",
  "net",
  "bind",
  "library",
  "format",
  "drc",
  "cli",
  "view",
] as const;

export type DiagnosticDomain = (typeof DIAGNOSTIC_DOMAINS)[number];

/** Severity. Independent of domain: emergent checks are warnings by nature. */
export type DiagnosticSeverity = "error" | "warning" | "note";

export interface DiagnosticCodeEntry {
  /** Domain. */
  readonly domain: DiagnosticDomain;
  /** Canonical severity of this code. */
  readonly severity: DiagnosticSeverity;
  /** One-sentence summary (for humans; also the source of the generated docs). */
  readonly summary: string;
  /** How to fix (optional). Call sites may give a more specific version; this is the fallback. */
  readonly hint?: string;
  /** Relevant spec / ADR references. */
  readonly spec: readonly string[];
}

