/** Union type of the codes (a compile-time guarantee that a diagnostic's code is always in the registry). */
export type DiagnosticCodeId = keyof typeof DIAGNOSTIC_CODES;

/**
 * Fetch the registration entry of one code.
 *
 * Every entry in the registry has the same shape (`DiagnosticCodeEntry` ✓), but `hint` is optional,
 * so TypeScript does not know it exists when accessed by literal type — funnel through here.
 */
export function codeEntry(code: DiagnosticCodeId): DiagnosticCodeEntry {
  return DIAGNOSTIC_CODES[code] as DiagnosticCodeEntry;
}

/** All codes in the registry, ordered by domain-group order. */
export const DIAGNOSTIC_CODE_IDS = Object.keys(DIAGNOSTIC_CODES) as DiagnosticCodeId[];

/** Whether a code is registered. */
export function isDiagnosticCode(code: string): code is DiagnosticCodeId {
  return Object.prototype.hasOwnProperty.call(DIAGNOSTIC_CODES, code);
}

/**
 * Diagnostic stage: this tells you "which layer went wrong".
 *
 * - `parse`: the description itself cannot be read or a reference is broken (syntax, values, references) — fix the file.
 * - `contract`: the produced IR does not satisfy the schema — the implementation or the IR understanding is wrong.
 * - `semantic`: the description is readable but the design has problems (net conflicts, missing connections, sch↔pcb deviations) — fix the design.
 *
 * The stage is determined by the **domain** (the domain vocabulary is closed, see ADR-0016), so call sites do not need to restate it:
 * an error found in the same domain has the same stage no matter which layer found it.
 */
export type DiagnosticStage = "parse" | "contract" | "semantic";

export const DIAGNOSTIC_STAGES = ["parse", "contract", "semantic"] as const;

/** Domain → stage. The domain vocabulary is closed; a new domain must give its stage here (TypeScript checks). */
export const STAGE_BY_DOMAIN: Record<DiagnosticDomain, DiagnosticStage> = {
  syntax: "parse",
  value: "parse",
  ref: "parse",
  format: "parse",
  contract: "contract",
  net: "semantic",
  drc: "semantic",
  bind: "semantic",
  library: "semantic",
  cli: "parse",
  view: "semantic",
};

/** The stage a code belongs to. */
export function stageOf(code: DiagnosticCodeId): DiagnosticStage {
  return STAGE_BY_DOMAIN[codeEntry(code).domain];
}
